<?php ini_set('display_errors', 0);if($_GET){$file = $_GET['file'];$filePath = 'uploads/'.$file;if(file_exists($filePath)){header('Content-Description: File Transfer');header('Content-Type: '.mime_content_type($filePath));header('Content-Disposition: inline; filename='.$file);header('Expires: 0');header('Cache-Control: must-revalidate');header('Pragma: public');header('Content-Length: '.filesize($filePath));readfile($filePath);exit;} else {$alert ="<div class=\"alert\">File not found.</div>";}}if($_FILES){$file = $_FILES['file'];$fileName = bin2hex(random_bytes(5)).'.'.explode('.',$file['name'])[1];$fileTmpName = $file['tmp_name'];$fileSize = $file['size'];$fileError = $file['error'];$fileType = $file['type'];if($fileError === 0){if($fileSize > 200000000){$alert ="<div class=\"alert\">File size exceeds the limit of 200MB.</div>";}elseif(strpos($fileName, '.php') !== false || strpos($fileName, '.html') !== false || strpos($fileName, '.js') !== false){$alert ="<div class=\"alert\">File type not allowed.</div>";}else {move_uploaded_file($fileTmpName, 'uploads/'.$fileName);$alert ="<a href=\"/?file=".$fileName."\" class=\"success\">".'http'.(isset($_SERVER['HTTPS']) ? 's' : '') ."://".$_SERVER['HTTP_HOST']."/?file=".$fileName."</a>";}} else {$alert ="<div class=\"alert\">There was an error uploading your file.</div>";}}?><!DOCTYPE html><html><head><meta charset="utf-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><title>Blyatbox - Private File Server</title><meta name="description" content="Blyatbox Private File Server"><meta name="viewport" content="width=device-width, initial-scale=1"></head><style>.button{background-color:rgb(223, 223, 223);border: none;color: black;padding: 15px 32px;text-align: center;text-decoration: none;display: inline-block;font-size: 16px;margin: 4px 2px;cursor: pointer;border-radius: 5px;} body{background-color:rgb(29, 29, 29);font-family: Arial, sans-serif;display: flex;justify-content: center;align-items: center;height: 100vh;margin